            ///   <para>
            ///     - <c>SDL_PROP_WINDOW_WAYLAND_DISPLAY_POINTER</c>: the wl_display associated with
            ///     the window
            ///     - <c>SDL_PROP_WINDOW_WAYLAND_SURFACE_POINTER</c>: the wl_surface associated with
            ///     the window
            ///     - <c>SDL_PROP_WINDOW_WAYLAND_VIEWPORT_POINTER</c>: the wp_viewport associated
            ///     with the window
