            /// <summary>
            ///   Set the swap interval for the current OpenGL context.
            /// </summary>
            /// <param name="interval">
            ///   0 for immediate updates, 1 for updates synchronized with
            ///   the vertical retrace, -1 for adaptive vsync.
            /// </param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <remarks>
            ///   <para>
            ///     Some systems allow specifying -1 for the interval, to enable adaptive
            ///     vsync. Adaptive vsync works the same as vsync, but if you've already missed
            ///     the vertical retrace for a given frame, it swaps buffers immediately, which
            ///     might be less jarring for the user during occasional framerate drops. If an
            ///     application requests adaptive vsync and the system does not support it,
            ///     this function will fail and return false. In such a case, you should
            ///     probably retry the call with 1 for the interval.
            ///   </para>
            ///   <para>
            ///     Adaptive vsync is implemented for some glX drivers with
            ///     GLX_EXT_swap_control_tear, and for some Windows drivers with
            ///     WGL_EXT_swap_control_tear.
            ///   </para>
            ///   <para>
            ///     Read more on the Khronos wiki:
            ///     https://www.khronos.org/opengl/wiki/Swap_Interval#Adaptive_Vsync
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   This function should only be called on the main thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GLGetSwapInterval"/>
            public static bool GLSetSwapInterval(int interval) => PInvoke.GLSetSwapInterval(interval) != 0;

            /// <summary>
            ///   Get the swap interval for the current OpenGL context.
            /// </summary>
            /// <param name="interval">
            ///   output interval value. 0 if there is no vertical retrace
            ///   synchronization, 1 if the buffer swap is synchronized with
            ///   the vertical retrace, and -1 if late swaps happen
            ///   immediately instead of waiting for the next retrace.
            /// </param>
            /// <returns>
            ///   true on success or false on failure; call SDL_GetError() for more
            ///   information.
            /// </returns>
            /// <remarks>
            ///   <para>
            ///     If the system can't determine the swap interval, or there isn't a valid
            ///     current context, this function will set *interval to 0 as a safe default.
            ///   </para>
            /// </remarks>
            /// <threadsafety>
            ///   This function should only be called on the main thread.
            /// </threadsafety>
            /// <since>
            ///   This function is available since SDL 3.2.0.
            /// </since>
            /// <seealso cref="Brutal.SdlApi.Sdl.PInvoke.GLSetSwapInterval"/>
            public static bool GLGetSwapInterval(out int interval)
            {
                interval = default;
                fixed (int* intervalPtr = &interval)
                {
                    return PInvoke.GLGetSwapInterval(intervalPtr) != 0;
                }
            }

